-- Authored instructions for the 2D workbench.
with revised(lesson_no,section) as (values
 (0,$data${"text":"Na karcie Home znajdziesz Draw (tworzenie obiektów), Modify (zmiany) i Layers (warstwy). Przejdź do pracowni, wybierz Draw → Prostokąt albo wpisz REC i Enter. Podaj pierwszy narożnik 0,0 i drugi @4200,3000. Obrys ma 4200 × 3000 jednostek. W tym zadaniu jedna jednostka oznacza 1 mm. Użyj Dopasuj widok, potem wybierz HATCH, wskaż wnętrze i potwierdź Enterem. Podgląd kreskowania zmieni się w zatwierdzone wypełnienie.","heading":"Od menu do pierwszego szkicu"}$data$::jsonb),
 (1,$data${"text":"Wstążka uruchamia narzędzie, a wiersz poleceń prowadzi przez jego etapy. Po kliknięciu Linia przeczytaj „Wskaż pierwszy punkt”. Po pierwszym punkcie zobaczysz kreskę podążającą za kursorem. Zatwierdź drugi punkt, aby powstał odcinek, a następnie wybierz Enter, by zakończyć. W dolnym pasku F7 przełącza siatkę, F9 skok siatki, F3 przyciąganie do geometrii, a F8 poziom i pion. Zmieniają sposób wskazywania, więc sprawdzaj, które są włączone.","heading":"Wstążka, wiersz poleceń i stan rysunku"}$data$::jsonb),
 (3,$data${"text":"Zapisz obok zadania, że 1 jednostka to 1 mm. W modelu wpisuj rzeczywisty wymiar: 4,2 m to 4200 jednostek. Powiększenie kółkiem zmienia ekran, więc po przybliżeniu polecenie DIST wciąż powinno podać tę samą odległość. W desktopowym AutoCAD w zakładce Layout ustawiasz format papieru i skalę rzutni. W pracowni Layout 1 pokazuje geometrię na arkuszu jako podgląd. Ćwiczenie skali: w 1:20 wymiar 4200 mm daje 210 mm na papierze.","heading":"Jednostka modelu, skala arkusza"}$data$::jsonb),
 (4,$data${"text":"W wierszu poleceń 1000,800 to punkt od początku układu. Wpis @500,-200 po nim daje 1500,600. Polecenie rozpoznaje również @600<30, czyli ruch o 600 jednostek pod kątem 30° od dodatniej osi X. Przecinek oddziela współrzędne X i Y, a część dziesiętną zapisz kropką, np. 175.5,80. Jeśli wpisany punkt jest poza bieżącym widokiem, możesz go nadal użyć. Wybierz Dopasuj widok po ukończeniu obiektu.","heading":"Współrzędne bez zgadywania"}$data$::jsonb),
 (5,$data${"text":"W LINE każdy zatwierdzony koniec od razu tworzy odcinek. Możesz podać następny punkt, użyć U, aby cofnąć ostatni odcinek, lub Enter, by zakończyć. PLINE łączy punkty w jeden obiekt. Wybierz Zamknij obrys przy trzech narożnikach. RECTANG wymaga dwóch przeciwległych narożników. CIRCLE oczekuje środka i promienia, a opcja D pozwala podać średnicę. Dla CIRCLE → 1000,900 → D → 600 promień wyniesie 300. Porównaj z okręgiem o promieniu 600.","heading":"Odcinek, obrys i promień"}$data$::jsonb),
 (6,$data${"text":"Enter zatwierdza punkt albo kończy sekwencję, zależnie od komunikatu. Przy LINE kliknij trzy punkty, a potem naciśnij Esc. Dwa zatwierdzone odcinki pozostaną na rysunku, a podgląd następnego zniknie. Jeśli przy prostokącie wskażesz tylko pierwszy narożnik i użyjesz Esc, nie zdążył powstać obiekt. U podczas LINE cofa ostatni odcinek w poleceniu. Ctrl+Z i Ctrl+Y cofają i ponawiają zmiany modelu. F2 pokazuje historię komunikatów.","heading":"Enter, Esc i wycofanie operacji"}$data$::jsonb),
 (7,$data${"text":"Otwórz Home → Layers albo wpisz LA. Utwórz warstwę Wymiary i zobacz, jak staje się aktywna. Wróć do Obrys, narysuj prostokąt, a później zmień warstwę na Osie i dodaj linię. Użyj Ukryj Osie i sprawdź, czy obrys nadal widać. Ponowne włączenie pokaże linię w tym samym miejscu. W projekcie rozdzielenie obrysu, osi i wymiarów ułatwia kontrolę widoku bez zmiany geometrii.","heading":"Warstwy przed rysowaniem"}$data$::jsonb),
 (9,$data${"text":"HATCH zaczynasz w Home → Draw albo aliasem H. Wybierz typ wypełnienia i wskaż wnętrze zamkniętej figury. Pracownia pokaże podgląd. Zatwierdź Enterem, aby zapisać kreskowanie, albo Esc, aby wrócić do szkicu. Dla polilinii otwartej sprawdź, czy brakuje zamknięcia. Zadanie: zbuduj obrys z punktów 500,500 → 2200,500 → 1400,1600, wybierz Zamknij obrys, potem wskaż 1400,850.","heading":"Wypełnianie zamkniętego obrysu"}$data$::jsonb),
 (10,$data${"text":"Na karcie Home wybierz Draw. Użyj REC i podaj -1000,-800, a potem @4200,3000. Pomiędzy tymi punktami powstanie prostokąt. Przy CIRCLE możesz wskazać drugi punkt na obwodzie albo wpisać promień. Przy ARC wskaż trzy niekollinearne punkty: początek, punkt na łuku i koniec. Spróbuj -800,0 → -400,400 → 0,0. Porównaj z łukiem dla trzech współliniowych punktów i odczytaj komunikat.","heading":"Dobierz polecenie do kształtu"}$data$::jsonb),
 (11,$data${"text":"Zaznacz krawędź, wybierz MOVE i wskaż bazę, a potem cel, np. 0,0 i @300,0. Przy braku zaznaczenia wskaż obiekt i potwierdź Enterem. COPY zachowa oryginał. ROTATE wymaga bazy i kąta, a SCALE bazy i dodatniego współczynnika. W OFFSET podaj odległość, wskaż linię lub okrąg, a potem stronę. TRIM w pracowni przycina prosty odcinek do widocznych, przecinających go krawędzi. Kliknij fragment do usunięcia i sprawdź, które części zostały.","heading":"Przesuń, skopiuj i dopasuj detal"}$data$::jsonb),
 (12,$data${"text":"F3 włącza OSNAP, który pomaga trafić w koniec, środek odcinka, środek okręgu albo jego kwadrant. Zbliż kursor do narożnika i obserwuj zielony znacznik. F8 ogranicza kierunek wskazywania kursorem do poziomu albo pionu. Wpis @200,100 nadal zadaje ten dokładny punkt. W desktopowym AutoCAD F12 steruje Dynamic Input, który może przyjmować dane przy kursorze. W pracowni F12 pokazuje odczyt przy wskaźniku, a współrzędne wpisujesz w wierszu poleceń.","heading":"F3 a F8 na tym samym zadaniu"}$data$::jsonb),
 (14,$data${"text":"W View wybierz Dopasuj · Zoom Extents, żeby objąć widoczne obiekty. Przybliż kółkiem w okolicy detalu. Przeciągnij środkowym przyciskiem albo wybierz PAN na ekranie dotykowym. Wróć do Dopasuj widok i sprawdź poleceniem DIST, czy odległość modelu została taka sama. Jeżeli duży fragment jest poza ekranem, najpierw dopasuj widok. Jeśli warstwa jest ukryta, włącz ją w Layers przed dopasowaniem.","heading":"Widok i położenie punktów"}$data$::jsonb),
 (16,$data${"text":"DIST (DI) mierzy odległość między dwoma punktami i podaje też różnicę X i Y. DIMLINEAR daje wymiar poziomy albo pionowy, a DIMALIGNED mierzy wzdłuż skośnej krawędzi. W Annotate wybierz Wymiar liniowy, podaj -1000,-800 i 3200,-800, a położenie linii wymiarowej ustaw niżej, np. 1000,-1450. Na rysunku zobaczysz 4200. Przejdź do Layout 1 i sprawdź, czy oznaczenie mieści się na arkuszu.","heading":"Długość odcinka i opis wymiaru"}$data$::jsonb),
 (19,$data${"text":"Utwórz obrys 4200 × 3000 mm, osobną warstwę Osie z odcinkiem poziomym, zamkniętą polilinię i okrąg o średnicy 600 mm. Wypełnij polilinię i dodaj wymiar szerokości obrysu. Zmierz odległość niezależnie przez DI. Zapisz w notatkach dwie kontrole: wynik 4200 i to, co widać po wyłączeniu warstwy Osie. Otwórz Arkusz i sprawdź, czy widać obrys, kreskowanie oraz wymiar.","heading":"Odbiór modelu pomieszczenia"}$data$::jsonb)
), prepared as (
 select l.lesson_no,r.section,coalesce((
  select jsonb_agg(case when item->>'heading'=r.section->>'heading' then r.section else item end order by position)
  from jsonb_array_elements(coalesce(l.material->'sections','[]'::jsonb)) with ordinality as original(item,position)
 ),'[]'::jsonb) as sections
 from public.ta_lessons l join revised r using(lesson_no) where l.course_slug='autocad-skroty'
), final as (
 select lesson_no,case when sections @> jsonb_build_array(section) then sections else sections||jsonb_build_array(section) end as sections from prepared
)
update public.ta_lessons l set material=jsonb_set(l.material,'{sections}',f.sections,true),updated_at=now()
from final f where l.course_slug='autocad-skroty' and l.lesson_no=f.lesson_no and l.material->'sections' is distinct from f.sections;
